head.script:
/************************************************************************************
 * ID           :	ULDSTF05950
 * File         :	ULDSTF05950.xml
 * Name         :	ELW 회원사알림 관리
 * Description  :	(as-is)lstproc/ULDSTF05950.gfm
 *                  탭 7개. AS-IS 는 전역변수 ELW_MBR_INFO_TP_CD(=탭 번호 1~7)로 분기했다.
 *                    1 상장제한종목 / 2 지수구성종목변동            — 등록·수정·삭제 (…/register|modify|remove-uly-chg)
 *                    3 발행가능 코스닥150 기초자산                  — 조회 (기준년월)
 *                    4 심사서류첨부(구분 3) / 5 기타안내(구분 4)     — 등록·수정·삭제 (…/register|modify|remove-decl-contn)
 *                    6 발행가능 KOSPI200 기초자산                   — 조회 (기준분기), 엑셀
 *                    7 발행가능행사가격                             — 조회 (기준년월·권리형태), 엑셀
 *                  API : /api/listing/lstproc/elw/mbr-noti/*  (사번은 서버가 세션에서 채운다)
 * Create Date  :	2026-10-26
************************************************************************************/

///////// 1. 변수 및 선언 영역 /////////

scwin.screenId = "ULDSTF05950";

scwin.curTp = 1;            // 현재 탭 번호 (AS-IS ELW_MBR_INFO_TP_CD, 1~7)
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제

// 심사서류첨부·기타안내 탭이 서버에 보내는 구분코드 (AS-IS fn_trs: 탭4 → "3", 탭5 → "4")
scwin.DECL_TP_CD = { 4: "3", 5: "4" };

// 탭별 상단 안내문 (AS-IS fn_SetTitle)
scwin.TITLE = {
    1: "* 발행사가 코드 발급한 ELW의 기초자산이 제한사유 해당종목이고 만기가 제한사유 발생시점 이후에 도래하는 경우\n  상장공시제출시스템의 상장신청 탭을 선택하였을때 안내 메시지를 표시합니다.",
    2: "* 발행사가 조회화면에 저장되어 있는 종목을 코드발급한 경우, 상장공시제출시스템의 상장신청 탭을 선택하였을때 안내 메시지를 표시합니다.",
    3: "",
    4: "* 지정한 표시기간 동안 발행사 담당자가 상장공시제출시스템의 공시제출 탭을 선택했을 때 팝업화면으로 내용에 입력한 사항을 표시합니다.",
    5: "* 메시지 표시기간은 입력값이 없으면 매월 말일 포함 직전 3영업일입니다."
};


///////// 2. 초기화 영역 /////////

scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF05950.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @description 초기화. 기준년월은 당월, 기준분기 콤보를 받고 상장제한종목 탭을 조회한다. (AS-IS onload)
 * @hidden N
*/
scwin.init = async function () {
    // inputCalendar validate
    $c.date.checkCalendarFormat(ica_StrtDd1, "yyyyMMdd");
    $c.date.checkCalendarFormat(ica_EndDd1, "yyyyMMdd");
    $c.date.checkCalendarFormat(ica_StrtDd2, "yyyyMMdd");

    $c.date.compareFromToDate(ica_StrtDd4, ica_EndDd4, ["메시지 표시기간 시작일자", "메시지 표시기간 종료일자"]);
    $c.date.compareFromToDate(ica_StrtDd5, ica_EndDd5, ["메시지 표시기간 시작일자", "메시지 표시기간 종료일자"]);

    dma_srch.set("chkYn", "Y");
    dma_srch.set("basYymm", $c.date.getServerDateTime("yyyyMM"));
    dma_srch.set("rghtTpCd", "C");

    await scwin.searchBasQtr();

    scwin.curTp = 1;
    MaxTab_01.setSelectedTabIndex(0);
    scwin.setTitle();
    scwin.setSearchCond();

    await scwin.listSync();
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.MaxTab_01_onchange
 * @description 탭 변경. 탭에 맞는 조회조건을 보이고 다시 조회한다. (AS-IS MaxTab_01 OnSelChanged)
 *  KOSPI200 탭은 기준분기를 첫 항목으로, 코스닥150·행사가격 탭은 기준년월을 당월로 되돌린다.
 * @hidden N
*/
scwin.MaxTab_01_onchange = async function (tabId, index) {
    try {
        scwin.curTp = MaxTab_01.getSelectedTabIndex() + 1;
        scwin.trJob = "";

        if (scwin.curTp === 6) {
            dma_srch.set("basQtr", dlt_basYymm.getRowCount() > 0 ? dlt_basYymm.getCellData(0, "value") : "");
        } else if (scwin.curTp === 3 || scwin.curTp === 7) {
            dma_srch.set("basYymm", $c.date.getServerDateTime("yyyyMM"));
        }
        scwin.setTitle();
        scwin.setSearchCond();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF05950.MaxTab_01_onchange" });
    }
};

scwin.btn_Search_onclick = async function () {
    try {
        if (!await scwin.checkSearch()) return;
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF05950.btn_Search_onclick" });
    }
};

/** 기준분기 변경 → 재조회 (AS-IS cmb_Bas_YYMM OnSelChange) */
scwin.cmb_BasQtr_onchange = async function () {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF05950.cmb_BasQtr_onchange" });
    }
};

/**
 * @event
 * @name scwin.btn_Excel_onclick
 * @description 엑셀 저장. (AS-IS btn_Excel / btn_Excel_1 — GridToExcel)
 * @hidden N
*/
scwin.btn_Excel_onclick = async function () {
    try {
        const grd = scwin.curTp === 6 ? grd_List_6 : grd_List_7;
        const dlt = scwin.curTp === 6 ? dlt_list6 : dlt_list7;
        const name = scwin.curTp === 6 ? "KOSPI 200 기초자산목록" : "발행가능행사가격";
        if (dlt.getRowCount() === 0) {
            await $c.win.alert("다운로드할 데이터가 없습니다.");
            return;
        }
        $c.data.downloadGridViewExcel(grd, { fileName: name + "_" + $c.date.getServerDateTime("yyyyMMddHHmmss"), sheetName: name });
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF05950.btn_Excel_onclick" });
    }
};

/** [신규] — 입력란을 비우고 입력 가능하게 (AS-IS btn_New_n: TR_JOB="I", fn_Enable_Item) */
scwin.btn_New_onclick = async function () {
    try {
        scwin.trJob = "I";
        scwin.clearForm();
        scwin.setFormMode("new");
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF05950.btn_New_onclick" });
    }
};

scwin.btn_Save_onclick = async function () {
    try { await scwin.save(); } catch (ex) { await $c.exception.handleError(ex, { context: "ULDSTF05950.btn_Save_onclick" }); }
};

scwin.btn_Delete_onclick = async function () {
    try { await scwin.remove(); } catch (ex) { await $c.exception.handleError(ex, { context: "ULDSTF05950.btn_Delete_onclick" }); }
};

scwin.btn_MakeInfo2_onclick = async function () {
    try { await scwin.makeInfo(); } catch (ex) { await $c.exception.handleError(ex, { context: "ULDSTF05950.btn_MakeInfo2_onclick" }); }
};

/**
 * @event
 * @name scwin.btn_FindCom_onclick
 * @description 종목(회사) 찾기. (AS-IS img_COM_NM_1/2 → fn_PopFindCorpChrg, 선택 시 ISUR_CD·COM_NM)
 * @hidden N
*/
scwin.btn_FindCom_onclick = async function () {
    try {
        const res = await $c.lc.popFindCorpChrg("");
        if ($c.util.isEmpty(res?.isurCd)) return;
        const dma = scwin.getItemMap();
        dma.set("isurCd", res.isurCd);
        dma.set("comNm", res.comNm ?? "");
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF05950.btn_FindCom_onclick" });
    }
};

/** 목록 클릭 → 입력란에 표시 (AS-IS grd_List_n OnClick → fn_SetValue) */
scwin.grd_List_oncellclick = async function (row, col) {
    try {
        scwin.setValue(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF05950.grd_List_oncellclick" });
    }
};


///////// 4. 서브미션 영역 /////////

/** 기준분기 콤보 (AS-IS fn_Bas_YYMM_sync) */
scwin.searchBasQtr = async function () {
    dlt_basYymm.removeAll();
    await $c.sbm.executeDynamic({
        id: "sbm_basYymm",
        method: "get",
        action: "/api/listing/lstproc/elw/mbr-noti/select-list-bas-yymm",
        target: "dlt_basYymm=body",
        isProcessMsg: false
    }, {});
};

/**
 * @method
 * @name scwin.listSync
 * @description 현재 탭 목록 조회. 입력란은 비우고 잠근 뒤, 상장제한종목·지수구성종목변동은 첫 건을 바로 보여 준다. (AS-IS fn_list_sync / OnLoadCompleted)
 * @hidden N
*/
scwin.listSync = async function () {
    const tp = scwin.curTp;
    if (scwin.getItemMap()) {
        scwin.clearForm();
        scwin.setFormMode("disabled");
    }

    const LIST = {
        1: { action: "/api/listing/lstproc/elw/mbr-noti/select-list-isu-lmt", param: { chkYn: dma_srch.get("chkYn") === "Y" ? "Y" : "N" } },
        2: { action: "/api/listing/lstproc/elw/mbr-noti/select-list-uly-chg", param: {} },
        3: { action: "/api/listing/lstproc/elw/mbr-noti/select-list-stridx-top5", param: { basYymm: dma_srch.get("basYymm") } },
        4: { action: "/api/listing/lstproc/elw/mbr-noti/select-list-decl-contn", param: { elwMbrInfoTpCd: scwin.DECL_TP_CD[4] } },
        5: { action: "/api/listing/lstproc/elw/mbr-noti/select-list-decl-contn", param: { elwMbrInfoTpCd: scwin.DECL_TP_CD[5] } },
        6: { action: "/api/listing/lstproc/elw/mbr-noti/select-list-uly-nm", param: { basYymm: dma_srch.get("basQtr") } },
        7: { action: "/api/listing/lstproc/elw/mbr-noti/select-list-exer-prc", param: { basYymm: dma_srch.get("basYymm"), rghtTpCd: dma_srch.get("rghtTpCd") } }
    }[tp];

    const dlt = scwin.getList(tp);
    dlt.removeAll();
    const result = await $c.sbm.executeDynamic({
        id: "sbm_list" + tp,
        method: "get",
        action: LIST.action,
        target: dlt.getID() + "=body"
    }, LIST.param);
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    if ((tp === 1 || tp === 2) && dlt.getRowCount() > 0) {
        scwin.getGrid(tp).setFocusedCell(0, 0);
        scwin.setValue(0);
    }
};

/**
 * @method
 * @name scwin.saveTrs
 * @description 저장(I)·수정(U)·삭제(D). (AS-IS fn_trs — 탭1/2 saveElwUlyChgInfo, 탭4/5 saveElwExchDeclInfo)
 * @returns {Promise<Boolean>} 처리 성공 여부
 * @hidden N
*/
scwin.saveTrs = async function (trJob) {
    const tp = scwin.curTp;
    const item = scwin.getItemMap().getJSON();
    let action = "";
    let requestData = {};

    if (tp === 1 || tp === 2) {
        action = { I: "/api/listing/lstproc/elw/mbr-noti/register-uly-chg", U: "/api/listing/lstproc/elw/mbr-noti/modify-uly-chg", D: "/api/listing/lstproc/elw/mbr-noti/remove-uly-chg" }[trJob];
        requestData = trJob === "D"
            ? { elwMbrInfoTpCd: String(tp), isurCd: item.isurCd, strtDd: item.strtDd }
            : {
                elwMbrInfoTpCd: String(tp),
                isurCd: item.isurCd,
                strtDd: item.strtDd,
                endDd: tp === 1 ? item.endDd : "",
                notiTitle: item.notiTitle,
                notiContn: item.notiContn
            };
    } else {
        action = { I: "/api/listing/lstproc/elw/mbr-noti/register-decl-contn", U: "/api/listing/lstproc/elw/mbr-noti/modify-decl-contn", D: "/api/listing/lstproc/elw/mbr-noti/remove-decl-contn" }[trJob];
        requestData = trJob === "D"
            ? { elwMbrInfoTpCd: scwin.DECL_TP_CD[tp], infoRnd: item.infoRnd }
            : {
                elwMbrInfoTpCd: scwin.DECL_TP_CD[tp],
                infoRnd: item.infoRnd,
                strtDd: item.strtDd,
                endDd: item.endDd,
                notiTitle: item.notiTitle,
                notiContn: item.notiContn
            };
    }

    const result = await $c.sbm.executeDynamic({
        id: "sbm_save",
        method: "post",
        action: action
    }, requestData);

    if (result?.skipped) return false;    // 진행 중 저장이 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return false;
    if (result.responseJSON.body?.result !== "S") {
        await $c.win.alert(result.responseJSON.body?.resultMessage ?? "처리에 실패했습니다.");
        return false;
    }
    return true;
};


///////// 5. 일반/업무 함수 영역 /////////

/** 탭 번호별 목록 dataList */
scwin.getList = function (tp) {
    return { 1: dlt_list1, 2: dlt_list2, 3: dlt_list3, 4: dlt_list4, 5: dlt_list5, 6: dlt_list6, 7: dlt_list7 }[tp];
};

/** 탭 번호별 그리드 */
scwin.getGrid = function (tp) {
    return { 1: grd_List_1, 2: grd_List_2, 3: grd_List_3, 4: grd_List_4, 5: grd_List_5, 6: grd_List_6, 7: grd_List_7 }[tp];
};

/** 현재 탭의 입력 dataMap (입력란이 없는 탭은 null) */
scwin.getItemMap = function () {
    return { 1: dma_item1, 2: dma_item2, 4: dma_item4, 5: dma_item5 }[scwin.curTp] ?? null;
};

/** "YYYY-MM-DD" → "YYYYMMDD" (지수구성종목변동·심사서류첨부·기타안내 목록은 하이픈 포함으로 내려온다) */
scwin.toDd = function (val) {
    return (val ?? "").replace(/-/g, "");
};

/** 허용되지 않는 문자(\ & < >) 포함 여부 (AS-IS fn_chkXss) */
scwin.chkXss = function (str) {
    return /[\\&<>]/.test(str ?? "");
};

/** 탭별 상단 안내문 (AS-IS fn_SetTitle — KOSPI200·행사가격 탭은 숨김) */
scwin.setTitle = function () {
    const text = scwin.TITLE[scwin.curTp];
    txb_Title.setValue(text ?? "");
    if (text === undefined) txb_Title.hide();
    else txb_Title.show("");
};

/**
 * @method
 * @name scwin.setSearchCond
 * @description 탭별 조회조건 표시. (AS-IS OnSelChanged 의 showObj)
 *  현재 유효한 항목만 보기: 상장제한종목 / 기준년월: 코스닥150·행사가격 / 기준분기: KOSPI200 / 권리형태: 행사가격
 *  엑셀은 KOSPI200·행사가격 탭에만 있다.
 * @hidden N
*/
scwin.setSearchCond = function () {
    const tp = scwin.curTp;
    const toggle = (comp, visible) => visible ? comp.show("") : comp.hide();
    toggle(grp_DelYn, tp === 1);
    toggle(grp_BasYymm, tp === 3 || tp === 7);
    toggle(grp_BasQtr, tp === 6);
    toggle(grp_RghtTpCd, tp === 7);
    toggle(btn_Excel, tp === 6 || tp === 7);
};

/** 현재 탭 입력란 비우기 */
scwin.clearForm = function () {
    scwin.getItemMap()?.setEmptyValue();
};

/**
 * @method
 * @name scwin.setFormMode
 * @description 입력란 상태. (AS-IS fn_Enable_Item / fn_Disable_Item / fn_SetValue)
 *  disabled: 모두 잠금
 *  new     : 모두 입력 가능
 *  update  : 상장제한종목·지수구성종목변동은 종목·시작일(키)을 잠그고 나머지만, 심사서류첨부·기타안내는 모두 입력 가능
 *  지수구분 콤보는 AS-IS 처럼 늘 선택 가능하다.
 * @hidden N
*/
scwin.setFormMode = function (mode) {
    const lock = mode === "disabled";
    const lockKey = mode !== "new";
    const tp = scwin.curTp;

    if (tp === 1) {
        btn_FindCom1.setDisabled(lockKey);
        ica_StrtDd1.setReadOnly(lockKey);
        ica_EndDd1.setReadOnly(lock);
        ibx_NotiTitle1.setReadOnly(lock);
        txa_NotiContn1.setReadOnly(lock);
    } else if (tp === 2) {
        btn_FindCom2.setDisabled(lockKey);
        ica_StrtDd2.setReadOnly(lockKey);
        txa_NotiContn2.setReadOnly(lock);
    } else if (tp === 4 || tp === 5) {
        const c = tp === 4
            ? [ibx_NotiTitle4, txa_NotiContn4, ica_StrtDd4, ica_EndDd4]
            : [ibx_NotiTitle5, txa_NotiContn5, ica_StrtDd5, ica_EndDd5];
        c.forEach(comp => comp.setReadOnly(lock));
    }
};

/**
 * @method
 * @name scwin.setValue
 * @description 목록 행을 입력란에 옮기고 수정 상태로. (AS-IS fn_SetValue)
 * @hidden N
*/
scwin.setValue = function (row) {
    const tp = scwin.curTp;
    const dma = scwin.getItemMap();
    if (!dma || row < 0) return;

    const r = scwin.getList(tp).getRowJSON(row);
    scwin.trJob = "U";
    if (tp === 1) {
        dma.setJSON({ isurCd: r.isurCd, comNm: r.comAbbrv, notiTitle: r.notiTitle, notiContn: r.notiContn, strtDd: r.strtDd, endDd: r.endDd });
    } else if (tp === 2) {
        dma.setJSON({ isurCd: r.isurCd, comNm: r.comAbbrv, notiTitle: r.notiTitle, notiContn: r.notiContn, strtDd: scwin.toDd(r.strtDd) });
    } else {
        dma.setJSON({ notiTitle: r.notiTitle, notiContn: r.notiContn, strtDd: scwin.toDd(r.strtDd), endDd: scwin.toDd(r.endDd), infoRnd: r.infoRnd });
    }
    scwin.setFormMode("update");
};

/** 조회조건 검사 — 기준년월(YYYYMM)·권리형태 (AS-IS btn_Search onclick, 행사가격 탭. 같은 기준년월을 쓰는 코스닥150 탭에도 적용) */
scwin.checkSearch = async function () {
    const tp = scwin.curTp;
    if (tp !== 3 && tp !== 7) return true;

    if (tp === 7 && $c.util.isEmpty(dma_srch.get("rghtTpCd"))) {
        await $c.win.alert("권리형태를 지정해주세요.");
        rdo_RghtTpCd.focus();
        return false;
    }
    const yymm = dma_srch.get("basYymm") ?? "";
    if ($c.util.isEmpty(yymm)) {
        await $c.win.alert("기준년월을 지정해주세요.");
        ibx_BasYymm.focus();
        return false;
    }
    if (yymm.length < 6) {
        await $c.win.alert("올바른 날짜형식이 아닙니다.(YYYYMM)");
        ibx_BasYymm.focus();
        return false;
    }
    const mm = Number(yymm.substring(4, 6));
    if (Number(yymm.substring(0, 1)) < 1 || mm > 12 || mm < 1) {
        await $c.win.alert("올바른 날짜형식이 아닙니다.");
        ibx_BasYymm.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.checkForm
 * @description 입력 검증. (AS-IS fn_CheckForm — 심사서류첨부는 삭제 시 검증 생략)
 * @hidden N
*/
scwin.checkForm = async function () {
    const tp = scwin.curTp;
    const item = scwin.getItemMap().getJSON();

    const fail = async (msg, comp) => {
        await $c.win.alert(msg);
        comp.focus();
        return false;
    };

    if (tp === 1) {
        if ($c.util.isEmpty(item.isurCd)) return fail("[종목명]를 입력하세요.", btn_FindCom1);
        if ($c.util.isEmpty(item.strtDd)) return fail("[제한사유 발생시점]을 입력하세요.", ica_StrtDd1);
        if ($c.util.isEmpty(item.endDd)) return fail("[제한사유 종료시점]을 입력하세요.", ica_EndDd1);
        if ($c.util.isEmpty(item.notiTitle)) return fail("[제한사유]를 입력하세요.", ibx_NotiTitle1);
        if (item.strtDd > item.endDd) return fail("[제한사유 종료시점]을  이전으로 입력하세요.", ica_StrtDd1);
    } else if (tp === 2) {
        if ($c.util.isEmpty(item.isurCd)) return fail("[종목명]를 입력하세요.", btn_FindCom2);
        if ($c.util.isEmpty(item.strtDd)) return fail("[지수편출일]을 입력하세요.", ica_StrtDd2);
        if ($c.util.isEmpty(item.notiTitle)) return fail("[지수구분]을 선택하세요.", cmb_NotiTitle2);
    } else if (tp === 4) {
        if (scwin.trJob === "D") return true;
        if ($c.util.isEmpty(item.notiTitle)) return fail("[제목]을 입력하세요.", ibx_NotiTitle4);
        if ($c.util.isEmpty(item.notiContn)) return fail("[내용]을 입력하세요.", txa_NotiContn4);
        if (scwin.chkXss(item.notiContn)) return fail("허용되지 않는 문자가 들어가 있습니다.", txa_NotiContn4);
        if ($c.util.isEmpty(item.strtDd)) return fail("[메시지 표시기간]을 입력하세요.", ica_StrtDd4);
        if ($c.util.isEmpty(item.endDd)) return fail("[메시지 표시기간]을 입력하세요.", ica_EndDd4);
        if (item.strtDd > item.endDd) return fail("[메시지 표시기간]의 시작일자는 종료일자보다 작아야 합니다.", ica_StrtDd4);
    } else if (tp === 5) {
        if ($c.util.isEmpty(item.notiTitle)) return fail("[제목]을 입력하세요.", ibx_NotiTitle5);
        if ($c.util.isEmpty(item.notiContn)) return fail("[내용]을 입력하세요.", txa_NotiContn5);
        if ($c.util.isEmpty(item.strtDd)) return fail("[메시지 표시기간]을 입력하세요.", ica_StrtDd5);
        if ($c.util.isEmpty(item.endDd)) return fail("[메시지 표시기간]을 입력하세요.", ica_EndDd5);
        if (item.strtDd > item.endDd) return fail("[메시지 표시기간]의 시작일자는 종료일자보다 작아야 합니다.", ica_StrtDd5);
    }
    return true;
};

/**
 * @method
 * @name scwin.save
 * @description 저장. [신규] 후면 등록, 목록 선택 후면 수정. (AS-IS fn_save)
 * @hidden N
*/
scwin.save = async function () {
    if (!scwin.getItemMap()) return;
    if (scwin.trJob !== "I" && scwin.trJob !== "U") {
        await $c.win.alert("[신규]를 누르거나 목록에서 수정할 건을 선택하세요.");
        return;
    }
    if (!await scwin.checkForm()) return;
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    const jobNm = scwin.trJob === "I" ? "저장" : "수정";
    if (!await scwin.saveTrs(scwin.trJob)) return;

    await $c.win.alert($c.data.getMessage("com_complete_0096", jobNm));
    scwin.trJob = "";
    await scwin.listSync();
};

/**
 * @method
 * @name scwin.remove
 * @description 삭제 (서버는 DEL_YN='Y' 논리삭제). (AS-IS fn_delete)
 * @hidden N
*/
scwin.remove = async function () {
    if (!scwin.getItemMap()) return;
    const prevJob = scwin.trJob;
    scwin.trJob = "D";
    if (!await scwin.checkForm() || !await $c.lc.isProcess("D")) {
        scwin.trJob = prevJob;
        return;
    }
    if (!await scwin.saveTrs("D")) {
        scwin.trJob = prevJob;
        return;
    }

    await $c.win.alert($c.data.getMessage("com_complete_0096", "삭제"));
    scwin.trJob = "";
    await scwin.listSync();
};

/**
 * @method
 * @name scwin.makeInfo
 * @description 지수구성종목변동 안내문 자동작성. (AS-IS fn_MakeInfo)
 * @hidden N
*/
scwin.makeInfo = async function () {
    if (!await scwin.checkForm()) return;
    const item = dma_item2.getJSON();
    const sDd = item.strtDd ?? "";
    const fmtDd = sDd.substring(0, 4) + "-" + sDd.substring(4, 6) + "-" + sDd.substring(6, 8);
    dma_item2.set("notiContn",
        item.comNm + " 종목이 " + fmtDd + " 에 " + item.notiTitle + " 에서 편출될 예정이므로 \n"
        + "해당 종목을 기초자산으로 하는 주식워런트증권은 상장이 불가합니다.\n"
        + "자세한 사항은 상품상장팀 담당자에게 문의하여 주시기 바랍니다.");
};
